const carsList = await browserjs(tabId, () => {
  const articles = Array.from(document.querySelectorAll('article')).filter(a => {
    return a.querySelector('h2, h3, h4') && !a.textContent.includes('Try these next') && !a.textContent.includes('Overwhelmed by options');
  });

  return articles.map(a => {
    const title = a.querySelector('h2, h3, h4')?.textContent?.trim();
    const text = a.textContent?.trim().replace(/\s+/g, ' ');
    const priceMatch = text.match(/\$[\d,]+/g);
    const milesMatch = text.match(/·\s*([\d]+K?\s*mi)/);
    const trimMatch = text.match(/([A-Za-z0-9\-]+)·[\d]+K?\s*mi/);
    const storeMatch = text.match(/(Grand Rapids \(Kentwood\)|[A-Za-z\s]+·\s*[\d.]+ mi)/);

    return {
      title,
      text,
      price: priceMatch ? priceMatch[priceMatch.length - 1] : null,
      miles: milesMatch ? milesMatch[1] : null,
      store: storeMatch ? storeMatch[0] : "Grand Rapids (Kentwood)"
    };
  });
});

